    integer k, mf = 0, mb = 0, nz = 0, ff = -1, fb = -1;
    function automatic [515:0] rnd516(input integer dummy);
        integer j; reg [543:0] t;
        begin for (j = 0; j < 17; j = j + 1) t[j*32 +: 32] = $random; rnd516 = t[515:0]; end
    endfunction
    initial begin
        if ($test$plusargs("FAR")) far = 1'b1;
        cid = $random;
        if ($test$plusargs("CID_ZERO")) cid = 0;
        $display("CB16_RESET_DIAG cid=%0h RPL=%0d QUIET=%0d", cid, RPL, QUIET);
        for (cyc = 0; cyc < N; cyc = cyc + 1) begin
            @(negedge ck);
            // mid-run resets last RPL edges (> the longest fabric path): pads keep stale words through a reset while landing rings
            // emit bubbles, so a die reset must flush the pipes (the fabric closes loops through t_out)
            rst_n = !(cyc < 20 || (cyc >= 2000 && cyc < 2000 + RPL) || (cyc >= 4100 && cyc < 4100 + RPL));
            // static schedule: no traffic is compiled into the reset window and the first QUIET edges after each release
            if (($test$plusargs("PRE_RESET_DRAIN") && ((cyc >= 1700 && cyc < 2000) || (cyc >= 3800 && cyc < 4100))) || cyc < 20 + QUIET || (cyc >= 2000 && cyc < 2000 + RPL + QUIET) || (cyc >= 4100 && cyc < 4100 + RPL + QUIET)) begin
                bc0 = '0; bc1 = '0; bc2 = '0; bc3 = '0; rs_i = '0; end
            else begin bc0 = rnd516(0); bc1 = rnd516(1); bc2 = rnd516(2); bc3 = rnd516(3); rs_i = rnd516(4); end
            @(posedge ck); #0.1;
            if (|ref_all) nz = nz + 1;
            if (cyc >= 2316 && cyc <= 2333) $display("CB16_RESET_EPOCH cyc=%0d rst=%b trst_ref=%b trst_full=%b trst_b=%b ref_t=%h full_t=%h",cyc,rst_n,u_ref.trst_0_0,u_f.trst_0_0,u_b.trst_0_0,u_ref.t_out_0_0[15:0],u_f.t_out_0_0[15:0]);
            if (!masked && f_all !== ref_all) begin mf = mf + 1; if (ff < 0) begin ff = cyc;
                for (k = 0; k < 3094; k = k + 1) if (f_all[k] !== ref_all[k]) begin $display("FULL_LOCKSTEP_MISMATCH dut=full cyc=%0d bit=%0d", cyc, k); k = 3094; end end end
            if (!masked && b_all !== ref_all) begin mb = mb + 1; if (fb < 0) begin fb = cyc;
                for (k = 0; k < 3094; k = k + 1) if (b_all[k] !== ref_all[k]) begin $display("FULL_LOCKSTEP_MISMATCH dut=fullb cyc=%0d bit=%0d", cyc, k); k = 3094; end end end
        end
        $display("FULL_LOCKSTEP_SUMMARY MF=%0d MB=%0d FAR=%0d cycles=%0d ref_nonzero=%0d mism_full=%0d mism_fullb=%0d", MF, MB, far, N, nz, mf, mb);
        if (mf == 0 && mb == 0 && nz > N / 2 && N > 4100 + RPL + QUIET + 500) begin $display("FULL_LOCKSTEP_PASS FAR=%0d", far); $finish; end
        else $fatal(1, "FULL_LOCKSTEP_FAIL");
    end
